actor Resequencer {
    private var window: [UInt64: Item] = [:]
    private var expected: UInt64 = 1
    func accept(_ item: Item) -> [Item] {          // actor-isolated window
        window[item.seq] = item                    // duplicates policy: keep last
        var ready: [Item] = []
        while let next = window.removeValue(forKey: expected) {
            ready.append(next); expected += 1      // ordered run
        }
        return ready                               // caller yields into AsyncStream
    }
}
